//! One shared closure formatter over borrowed actual dependency facts.
use std::{fmt::Write as _,io};
use crate::{reactive_dependency_view::Analysis,reactive_read_facts::ENGINE_DIRS,key_policy_control::{self as kc,Control}};
pub(crate)trait Lines{fn line(&self,relative:&str,line:u32)->Option<&str>;}
trait Matches{fn visit<'a>(&self,line:&'a str,emit:&mut dyn FnMut(&'a str)->io::Result<()>)->io::Result<()>;}
#[cfg(feature="native-policy")]struct NativeMatches<'a>(&'a dyn crate::native_pattern::Provider);
#[cfg(feature="native-policy")]impl Matches for NativeMatches<'_>{fn visit<'a>(&self,line:&'a str,emit:&mut dyn FnMut(&'a str)->io::Result<()>)->io::Result<()>{let spec=crate::native_pattern::Spec{pattern:r"\bvg_\w+",mode:crate::native_pattern::Mode::Search};let mut offset=0;loop{let mut next=None;let found=self.0.find(spec,line,offset,&mut|(start,end)|{if next.is_some()||start<offset||end<=start||end>line.len(){return Err(io::ErrorKind::InvalidData.into())}emit(line.get(start..end).ok_or(io::ErrorKind::InvalidData)?)?;next=Some(end);Ok(())})?;match(found,next){(false,None)=>return Ok(()),(true,Some(end))=>offset=end,_=>return Err(io::ErrorKind::InvalidData.into())}}}}
#[cfg(feature="legacy-sem")]struct LegacyMatches;
#[cfg(feature="legacy-sem")]impl Matches for LegacyMatches{fn visit<'a>(&self,line:&'a str,emit:&mut dyn FnMut(&'a str)->io::Result<()>)->io::Result<()>{for matched in crate::pat!(r"\bvg_\w+").find_iter(line){emit(matched.as_str())?;}Ok(())}}
type Key<'a>=(&'static str,&'a str,u32,&'a str);
#[derive(Eq,PartialEq,Ord,PartialOrd)]struct Flat<'a>{key:Key<'a>,consumer:&'a str}
fn collect<'a,C:Control<Error=io::Error>>(a:Analysis<'a>,c:&mut C)->io::Result<Vec<Flat<'a>>>{let mut rows=Vec::new();for(id,reads)in a.consumers(){for read in reads{c.checkpoint()?;if read.rel.is_empty()||read.line==0{continue}kc::row(c,&mut rows)?;rows.push(Flat{key:(if a.is_draw(id){"draw_untracked"}else{"stat_input_untracked"},&read.rel,read.line,&read.what),consumer:id});}}rows.sort_unstable();rows.dedup();Ok(rows)}
fn groups<'a,'s,C:Control<Error=io::Error>>(rows:&'a[Flat<'s>],c:&mut C)->io::Result<Vec<(&'a Key<'s>,usize)>>{let mut out=Vec::new();let mut first=0;while first<rows.len(){c.checkpoint()?;let mut end=first+1;while end<rows.len()&&rows[end].key==rows[first].key{end+=1}kc::row(c,&mut out)?;out.push((&rows[first].key,end-first));first=end;}Ok(out)}
fn category(w:&str)->&'static str{match w{w if w.starts_with("?opaque:")=>"opaque crossing","?unannotated_global"=>"unannotated global proc","?dynamic_read"=>"vars[] / call()","?hop_not_relation"=>"hop through a non-relation var","?ffi_call"=>"Verdigris FFI call",w if w.starts_with("GLOB.")||w.starts_with("SS")&&!w.contains(' ')&&w.chars().nth(2).is_some_and(|c|c.is_ascii_lowercase())=>"dynamic global state",_=>"untracked var read"}}
fn area(s:&str)->&str{s.match_indices('/').nth(1).map_or(s,|(end,_)|&s[..end])}
fn in_engine(s:&str)->bool{ENGINE_DIRS.iter().any(|d|s.starts_with(d))}
fn units(rows:&[(&Key<'_>,usize)],rule:&str)->usize{rows.iter().filter(|(s,_)|s.0==rule).map(|(_,n)|*n).sum()}
fn tally<C:Control<Error=io::Error>,K:Ord>(keys:impl Iterator<Item=K>,c:&mut C)->io::Result<Vec<(K,usize)>>{let mut out:Vec<(K,usize)>=Vec::new();for key in keys{c.checkpoint()?;kc::row(c,&mut out)?;out.push((key,1));}out.sort_unstable_by(|a,b|a.0.cmp(&b.0));let mut write=0;for read in 0..out.len(){if write>0&&out[write-1].0==out[read].0{out[write-1].1=out[write-1].1.checked_add(1).ok_or(io::ErrorKind::OutOfMemory)?;}else{if write!=read{out.swap(write,read)}write+=1;}}out.truncate(write);Ok(out)}
struct Out<'a,C>{text:String,c:&'a mut C,first:Option<io::Error>}
impl<C:Control<Error=io::Error>>std::fmt::Write for Out<'_,C>{fn write_str(&mut self,s:&str)->std::fmt::Result{if self.first.is_some(){return Err(std::fmt::Error)}let result=(||{self.c.checkpoint()?;let n=self.text.len().checked_add(s.len()).ok_or_else(||self.c.overflow())?;if n>self.text.capacity(){let target=n.max(self.text.capacity().saturating_mul(2)).max(64);let peak=target.checked_mul(4).and_then(|n|n.checked_add(self.text.capacity())).ok_or_else(||self.c.overflow())?;self.c.temporary(1,peak)?;self.text.try_reserve_exact(target-self.text.len()).map_err(|_|self.c.allocation_failed())?;if self.text.capacity()>target.saturating_mul(4){return Err(self.c.allocation_failed())}}self.text.push_str(s);Ok(())})();match result{Ok(())=>Ok(()),Err(first)=>{self.first=Some(first);Err(std::fmt::Error)}}}}
fn render<C:Control<Error=io::Error>>(base:Analysis<'_>,closed:Analysis<'_>,lines:&impl Lines,patterns:&impl Matches,c:&mut C)->io::Result<String>{let b=collect(base,c)?;let a=collect(closed,c)?;let before=groups(&b,c)?;let after=groups(&a,c)?;let mut new=Vec::new();for &(key,n)in &after{c.checkpoint()?;if before.binary_search_by(|(old,_)|(*old).cmp(key)).is_err(){kc::row(c,&mut new)?;new.push((key,n));}}let gone=before.iter().filter(|(key,_)|after.binary_search_by(|(old,_)|(*old).cmp(key)).is_err()).count();let new_keys=||new.iter().map(|(key,_)|*key);let engine_side=new_keys().filter(|s|in_engine(s.1)).count();let count=|rows:&[(&Key<'_>,usize)],rule:&str|rows.iter().filter(|(s,_)|s.0==rule).count();
 let by_cat=tally(new_keys().map(|s|(category(s.3),s.0)),c)?;let mut cats=Vec::new();for((cat,_),_)in &by_cat{if cats.last()!=Some(cat){kc::row(c,&mut cats)?;cats.push(*cat)}}
 let mut areas=tally(new_keys().map(|s|area(s.1)),c)?;areas.sort_unstable_by(|a,b|b.1.cmp(&a.1).then(a.0.cmp(b.0)));let mut files=tally(new_keys().map(|s|s.1),c)?;files.sort_unstable_by(|a,b|b.1.cmp(&a.1).then(a.0.cmp(b.0)));
 let mut unwalkable=Vec::new();for s in new_keys().filter(|s|in_engine(s.1)){let cat=category(s.3);if cat!="untracked var read"{kc::row(c,&mut unwalkable)?;unwalkable.push((s.1,cat,s.2));}}unwalkable.sort_unstable();unwalkable.dedup();
 let mut ffi=Vec::new();for s in new_keys().filter(|s|s.3=="?ffi_call"){c.checkpoint()?;if let Some(line)=lines.line(s.1,s.2){patterns.visit(line,&mut|word|{kc::row(c,&mut ffi)?;ffi.push(word);Ok(())})?;}}ffi.sort_unstable();ffi.dedup();let mut out=Out{text:String::new(),c,first:None};
    let _ = writeln!(out, "# Reads closure\n");
    let _ = writeln!(out, "Generated by `analyze sem closure --write`. Do not edit by hand; it is deterministic for a tree.\n\n");
    let _ = writeln!(out, "`untracked_inputs` and `sem/reads` used to judge a read walk that skipped the engine-internal directories, followed a call on the receiver's static type only and");
    let _ = writeln!(out, "stopped at every global proc without `READS_FROM`. They now judge the closed walk (`ReadsEngine::closed`, the one the generated subscriptions already used): engine bodies are");
    let _ = writeln!(out, "entered, a virtual call is the union of its overrides, a global proc is walked like any proc, and global state is classified (`sem/globals.rs`: written only while the world boots,");
    let _ = writeln!(out, "so it reads like a constant; a tracked var of a system; anything else is an input nothing publishes). **This is a change of measurement, not new debt.** The baselines were");
    let _ = writeln!(out, "re-seeded once, counted per site (a line read by six hundred draws is one line), and only shrink from here. Legacy walk below is the old measurement, closed walk the new one.\n");
    let _ = writeln!(out, "| | draw_untracked | stat_input_untracked | total |\n|---|---:|---:|---:|");
    let _ = writeln!(out, "| legacy walk | {} | {} | {} |", count(&before, "draw_untracked"), count(&before, "stat_input_untracked"), before.len());
    let _ = writeln!(out, "| closed walk | {} | {} | {} |", count(&after, "draw_untracked"), count(&after, "stat_input_untracked"), after.len());
    let newd = new_keys().filter(|s| s.0 == "draw_untracked").count();
    let _ = writeln!(out, "| **newly visible** | {} | {} | {} |", newd, new.len() - newd, new.len());
    let _ = writeln!(out, "| no longer reported (walked into) | | | {} |\n", gone);
    // The baseline file holds one line per (consumer, line): the number a baseline decision has to cover.
    let (bd,bs)=(units(&before,"draw_untracked"),units(&before,"stat_input_untracked"));
    let (cd,cs)=(units(&after,"draw_untracked"),units(&after,"stat_input_untracked"));
    let (nd,ns)=(units(&new,"draw_untracked"),units(&new,"stat_input_untracked"));
    let _ = writeln!(out, "The same, counted the way the old `untracked_inputs_baseline.txt` counted (one line per consumer that reaches a site, so a helper line read by ten draws is ten lines; the new baseline counts sites, the table above):\n");
    let _ = writeln!(out, "| | draw_untracked | stat_input_untracked | total |\n|---|---:|---:|---:|");
    let _ = writeln!(out, "| legacy walk | {} | {} | {} |", bd, bs, bd + bs);
    let _ = writeln!(out, "| closed walk | {} | {} | {} |", cd, cs, cd + cs);
    let _ = writeln!(out, "| **newly visible** | {} | {} | {} |\n", nd, ns, nd + ns);

    let _ = writeln!(out, "## Newly visible, by category\n");
    let _ = writeln!(out, "| category | draw | stat input | total |\n|---|---:|---:|---:|");
 for cat in cats{let d=by_cat.iter().find_map(|((actual,rule),n)|(*actual==cat&&*rule=="draw_untracked").then_some(*n)).unwrap_or(0);let st=by_cat.iter().find_map(|((actual,rule),n)|(*actual==cat&&*rule=="stat_input_untracked").then_some(*n)).unwrap_or(0);let _=writeln!(out,"| {} | {} | {} | {} |",cat,d,st,d+st);}
 let _=writeln!(out,"\nOf the {} newly visible sites, **{}** sit in engine-internal files (the directories the lints' walk skips) and {} in content reached through a virtual call or through the engine.\n",new.len(),engine_side,new.len()-engine_side);
 let _=writeln!(out,"## Newly visible, by area\n");let _=writeln!(out,"| area | sites |\n|---|---:|");for(a,n)in areas.iter().take(40){let _=writeln!(out,"| `{}` | {} |",a,n);}
 let _=writeln!(out,"\n## Newly visible, top files\n");let _=writeln!(out,"| file | sites |\n|---|---:|");for(f,n)in files.iter().take(40){let _=writeln!(out,"| `{}` | {} |",f,n);}
 let _=writeln!(out,"\n## Constructs the walk cannot resolve inside the engine (want a `PROC_SUMMARY`)\n");let _=writeln!(out,"`vars[]`/`call()`, a global proc without `READS_FROM`, a Verdigris FFI call, or a hop through a var that is not a declared relation, found in an engine-internal body.");let _=writeln!(out,"`PROC_SUMMARY(path, reads = list(...), writes = list(...))` (`code/defines/engine/declare/markers.dm`) declares what such a proc touches; the walk then takes the summary in place of the body.\n");let _=writeln!(out,"| file | construct | lines |\n|---|---|---|");
 let mut first=0;while first<unwalkable.len(){let(file,cat,_)=unwalkable[first];let mut end=first+1;while end<unwalkable.len()&&unwalkable[end].0==file&&unwalkable[end].1==cat{end+=1}let _=write!(out,"| `{}` | {} | ",file,cat);for(index,(_,_,line))in unwalkable[first..end].iter().take(12).enumerate(){if index!=0{let _=write!(out,", ");}let _=write!(out,"{line}");}let _=writeln!(out,"{} |",if end-first>12{", ..."}else{""});first=end;}
 if unwalkable.is_empty(){let _=writeln!(out,"| (none) | | |");}let _=write!(out,"\nVerdigris FFI procs a handler or draw reaches ({}): ",ffi.len());for(index,name)in ffi.iter().enumerate(){if index!=0{let _=write!(out,", ");}let _=write!(out,"`{}`",name);}let _=writeln!(out,"\n");
 let _=writeln!(out,"## Every newly visible site\n");let _=writeln!(out,"`rule | file:line | read | consumers reaching it`\n");for(s,n)in &new{let _=writeln!(out,"- {} | {}:{} | `{}` | {}",s.0,s.1,s.2,s.3,n);}match out.first{Some(first)=>Err(first),None=>Ok(out.text)}
}
#[cfg(feature="native-policy")]pub(crate)fn report_admitted<C:Control<Error=io::Error>>(base:Analysis<'_>,closed:Analysis<'_>,lines:&impl Lines,provider:&dyn crate::native_pattern::Provider,c:&mut C)->io::Result<String>{render(base,closed,lines,&NativeMatches(provider),c)}
#[cfg(feature="legacy-sem")]pub(crate)fn report(base:Analysis<'_>,closed:Analysis<'_>,lines:&impl Lines)->String{struct Legacy;impl Control for Legacy{type Error=io::Error;const CHECKED:bool=false;fn checkpoint(&mut self)->io::Result<()>{Ok(())}fn reserve(&mut self,_:usize)->io::Result<()>{Ok(())}fn overflow(&mut self)->io::Error{io::ErrorKind::OutOfMemory.into()}fn allocation_failed(&mut self)->io::Error{io::ErrorKind::OutOfMemory.into()}}render(base,closed,lines,&LegacyMatches,&mut Legacy).expect("ordinary closure report allocation failed")}
